package com.testora.service;
import com.testora.config.DBConnection; import java.io.*; import java.sql.*; import java.util.*;
/** CSV import/export service; input is deliberately simple comma-separated practical data. */
public class CsvService { public int importProblems(File file)throws Exception{Set<String> seen=new HashSet<>();try(BufferedReader r=new BufferedReader(new FileReader(file));Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO problems(title,slug,description,difficulty,starter_code,topic_id,time_limit_sec,max_marks) VALUES(?,?,?,?,?,?,?,?)")){String line;int n=0;while((line=r.readLine())!=null){String[] x=line.split(",",-1);if(x.length<8||!seen.add(x[1]))continue;p.setString(1,x[0]);p.setString(2,x[1]);p.setString(3,x[2]);p.setString(4,x[3]);p.setString(5,x[4]);p.setLong(6,Long.parseLong(x[5]));p.setInt(7,Integer.parseInt(x[6]));p.setInt(8,Integer.parseInt(x[7]));p.addBatch();n++;}p.executeBatch();return n;}} // SYLLABUS: BufferedReader FileReader HashSet addBatch
 public void exportProblems(File file)throws Exception{try(BufferedWriter w=new BufferedWriter(new FileWriter(file));Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT id,title,slug,difficulty FROM problems");ResultSet r=p.executeQuery()){w.write("id,title,slug,difficulty\n");while(r.next())w.write(r.getLong(1)+","+r.getString(2)+","+r.getString(3)+","+r.getString(4)+"\n");}try(FileInputStream in=new FileInputStream(file);FileOutputStream out=new FileOutputStream(file.getPath()+".bak")){in.transferTo(out);}} // SYLLABUS: buffered/binary file IO
 public List<String> importTextQuestions(File file)throws Exception{List<String>a=new ArrayList<>();try(FileReader reader=new FileReader(file)){StreamTokenizer t=new StreamTokenizer(reader);while(t.nextToken()!=StreamTokenizer.TT_EOF)if(t.ttype==StreamTokenizer.TT_WORD)a.add(t.sval);}return a;} // SYLLABUS: StreamTokenizer
}
